package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.User;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
@WebServlet(urlPatterns={"/admin/reports","/security/history","/staff/reports","/admin/audit","/admin/export-scans"}) public class ReportServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession().getAttribute("user");try{String path=r.getServletPath(),dept="STAFF".equals(u.getRole())?u.getDepartment():null;if(path.endsWith("export-scans")){export(s,new ScanDao().list(10000,null));return;}if(path.endsWith("audit")){r.setAttribute("auditLogs",new AuditDao().list(300));r.getRequestDispatcher("/WEB-INF/views/admin/audit.jsp").forward(r,s);return;}r.setAttribute("scanLogs",new ScanDao().list(500,dept));r.setAttribute("weekly",new ScanDao().weekly());String page=path.contains("security")?"security/history.jsp":path.contains("staff")?"staff/reports.jsp":"admin/reports.jsp";r.getRequestDispatcher("/WEB-INF/views/"+page).forward(r,s);}catch(Exception e){throw new ServletException(e);}}
 private void export(HttpServletResponse s,List<Map<String,Object>> rows)throws IOException{s.setContentType("text/csv;charset=UTF-8");s.setHeader("Content-Disposition","attachment; filename=qrid-scan-report.csv");PrintWriter w=s.getWriter();w.println("identity_no,full_name,department,gate_location,result,verified_by,scanned_at");for(Map<String,Object>x:rows){w.println(csv(x.get("identity_no"))+","+csv(x.get("full_name"))+","+csv(x.get("department"))+","+csv(x.get("gate_location"))+","+csv(x.get("result"))+","+csv(x.get("verified_by"))+","+csv(x.get("scanned_at")));}}
 private String csv(Object o){String v=o==null?"":String.valueOf(o);return "\""+v.replace("\"","\"\"")+"\"";}
}
